authors.example:
allUsers(first: Int, after: String): UserConnection!
  @mongo__connection(
    collection: "users"
    first: "$args.first"
    after: "$args.after"
    selection: """
nodes {
  id: _id
  name
}
"""
  )

usersPage(page: Int, perPage: Int): UserPage!
  @mongo__pagination(
    collection: "users"
    page: "$args.page"
    perPage: "$args.perPage"
    selection: """
items {
  id: _id
  name
}
"""
  )
